<template>
    <div class="sso-login">
        <div v-if="loading" class="loading">
            正在进入...
        </div>
    </div>
</template>

<script>
import {
    iotSsoLogin
}  from '@/api/iot'
import store from '@/store'
export default {
    name: 'SSOLogin',
    data() {
        return {
            loading: true
        }
    },
    created() {
        this.handleSSOLogin()
    },
    methods: {
        async handleSSOLogin() {
            try {
                // 从URL获取SSO Token
                const ssoToken = this.getQueryParam('itoken')
                console.log('ssoToken:', ssoToken)
                const app = this.getQueryParam('app')
                
                if (!ssoToken) {
                    this.$router.push('/')
                    return
                }

                // 发送验证请求
                const result = await iotSsoLogin({
                    token: ssoToken,
                    app: app
                })

                let user = result.user
                user.token = result.token.token
                
                await store.dispatch('user/login', user)
                this.$cache.setExpire('sso_auth', 1)
                setTimeout(() => {
                    this.$router.push('/vip/products')
                }, 1000)
            } catch (error) {
                console.error('SSO验证失败:', error)
                await store.dispatch('user/resetToken')
                this.$router.push('/')
            } finally {
                this.loading = false
            }
        },
        getQueryParam(name) {
            const urlParams = new URLSearchParams(window.location.search)
            return urlParams.get(name)
        }
    }
}
</script>

<style scoped>
.sso-login {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
}
.loading {
    font-size: 16px;
    color: #666;
}
</style>